(() => {
  const real = window.fetch ? window.fetch.bind(window) : null;

  window.fetch = (input, init) => {
    const url = String(input && input.url ? input.url : input);
    const mark = url.indexOf("?");
    const path = mark < 0 ? url : url.slice(0, mark);

    if (!path.endsWith("/content/")) {
      return real ? real(input, init) : Promise.reject(new Error("fetch 없음"));
    }

    const params = new URLSearchParams(mark < 0 ? "" : url.slice(mark + 1));

    /* 빌드할 때와 같은 방법으로 키를 만든다. JSON 형식 차이에 기대지 않는다. */
    const sep = String.fromCharCode(31);
    const key = [
      params.get("mind_1"),
      params.get("mind_2"),
      params.get("mind_3"),
    ].join(sep);

    const found = window.HT_OFFLINE.flows[key];
    const reply = (body, status) =>
      Promise.resolve(
        new Response(JSON.stringify(body), {
          status,
          headers: { "Content-Type": "application/json" },
        }),
      );

    if (!found) return reply({ error: "해당 선택 흐름을 찾지 못했다." }, 404);

    const { space_id: spaceId, ...rest } = found;
    return reply({ ...rest, space: window.HT_OFFLINE.spaces[spaceId] }, 200);
  };
})();

/* file:// 에서는 브라우저가 history.pushState를 막기도 한다. 막히면 공간 상세의
   `X`가 뒤로가기를 거치지 않고 바로 닫는다(app.js가 그렇게 갈라 둔다). */
(() => {
  const push = window.history.pushState.bind(window.history);
  window.history.pushState = (...args) => {
    try {
      push(...args);
    } catch (error) {
      console.warn("pushState를 쓸 수 없다. X로만 닫는다.", error);
    }
  };
})();
